pub fn realize_route<T: Clone>(lookup: Rc<CacheLookupResult<T>>) -> Rc<RealizeRoute<T>> {
    match (*lookup.clone()).clone() {
    CacheLookupResult::Hit { receipt: receipt, .. } => Rc::new(RealizeRoute::Reuse {
    receipt: receipt.clone(),
}),
    CacheLookupResult::Miss => Rc::new(RealizeRoute::Recompute {
    reason: RecomputeReason::SubjectAbsent,
}),
    CacheLookupResult::RejectedHit { reason: r, .. } => rejected_hit_route(r.clone()),
}
}

pub fn rejected_hit_route<T>(reason: Rc<CacheRejectReason>) -> Rc<RealizeRoute<T>> {
    match (*reason.clone()).clone() {
    CacheRejectReason::FreshnessExpired => Rc::new(RealizeRoute::Recompute {
    reason: RecomputeReason::InvalidationFired,
}),
    CacheRejectReason::SubjectDigestMismatch => Rc::new(RealizeRoute::Refuse {
    reason: Rc::new(RefuseReason::HitRefused {
    reason: reason.clone(),
}),
}),
    CacheRejectReason::ContentDigestMismatch => Rc::new(RealizeRoute::Refuse {
    reason: Rc::new(RefuseReason::HitRefused {
    reason: reason.clone(),
}),
}),
    CacheRejectReason::ProducerReceiptMissing => Rc::new(RealizeRoute::Refuse {
    reason: Rc::new(RefuseReason::HitRefused {
    reason: reason.clone(),
}),
}),
    CacheRejectReason::BackendKeyMalformed => Rc::new(RealizeRoute::Refuse {
    reason: Rc::new(RefuseReason::HitRefused {
    reason: reason.clone(),
}),
}),
    CacheRejectReason::BackendUnauthorized => Rc::new(RealizeRoute::Refuse {
    reason: Rc::new(RefuseReason::HitRefused {
    reason: reason.clone(),
}),
}),
    CacheRejectReason::BackendUnavailable => Rc::new(RealizeRoute::Refuse {
    reason: Rc::new(RefuseReason::HitRefused {
    reason: reason.clone(),
}),
}),
    CacheRejectReason::TransportFaithfulnessFailure { reason: _, .. } => Rc::new(RealizeRoute::Refuse {
    reason: Rc::new(RefuseReason::HitRefused {
    reason: reason.clone(),
}),
}),
}
}

pub fn classify_write<T: Clone>(existing: Rc<CacheLookupResult<T>>, offered_content: Rc<ContentHash>, fresh_receipt: Rc<CachedArtifactReceipt<T>>) -> Rc<CacheWriteResult<T>> {
    match (*existing.clone()).clone() {
    CacheLookupResult::Miss => Rc::new(CacheWriteResult::Written {
    receipt: fresh_receipt.clone(),
}),
    CacheLookupResult::Hit { receipt: receipt, .. } => if (receipt.content_digest.clone() == offered_content.clone()) {
        Rc::new(CacheWriteResult::WriteSkippedIdempotent {
    receipt: receipt.clone(),
})
    } else {
        Rc::new(CacheWriteResult::WriteRejected {
    reason: Rc::new(CacheWriteRejectReason::WriteOnceConflict),
})
    },
    CacheLookupResult::RejectedHit { reason: r, .. } => Rc::new(CacheWriteResult::WriteRejected {
    reason: Rc::new(CacheWriteRejectReason::BackendWriteRejected {
    backend_reason: r.clone(),
}),
}),
}
}

